// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint96 fundAmount, address caller) public {
        uint256 amount = bound(fundAmount, 1, type(uint96).max);
        vm.assume(caller != address(0));

        vm.deal(address(this), amount);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);
        assertEq(address(c).balance, amount);

        vm.deal(caller, 1 ether);
        vm.prank(caller);
        try c.withdrawAll(caller) {
        } catch {
        }

        if (caller == address(this)) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance > 0);
        }
    }
}
